/// The items below are pub(crate).
/// One open document in the document list.
#[derive(Clone, Debug, PartialEq, Eq)]
struct DocRow {
    pub document: kate_core::DocumentId,
    pub name: String,
    pub path: Option<std::path::PathBuf>,
    pub modified: bool,
    pub active: bool,
}

/// The items below are pub(crate).
/// Every open document sorted by name without regard to case.
fn document_rows(ws: &kate_core::Workspace) -> Vec<DocRow>
